def at_most_k_distinct(nums, k):
    if k < 0:
        return 0
    freq = {}
    left = 0
    total = 0
    for right in range(len(nums)):
        val = nums[right]
        if val in freq:
            freq[val] += 1
        else:
            freq[val] = 1
        while len(freq) > k:
            left_val = nums[left]
            freq[left_val] -= 1
            if freq[left_val] == 0:
                del freq[left_val]
            left += 1
        total += right - left + 1
    return total


def exact_k_distinct(nums, k):
    return at_most_k_distinct(nums, k) - at_most_k_distinct(nums, k - 1)


def longest_ones_with_k_flips(bits, k):
    left = 0
    zeros = 0
    best = 0
    for right in range(len(bits)):
        if bits[right] == 0:
            zeros += 1
        while zeros > k:
            if bits[left] == 0:
                zeros -= 1
            left += 1
        span = right - left + 1
        if span > best:
            best = span
    return best


# ১) হাতে-কলমে উদাহরণ যাচাই
