from collections import deque


def sliding_window_max(nums, w):
    if len(nums) == 0 or w <= 0:
        return []
    dq = deque()  # ক্রমহ্রাসমান মানের Index ধরে রাখে
    out = []
    for r in range(len(nums)):
        val = nums[r]
        while len(dq) > 0 and dq[0] <= r - w:
            dq.popleft()
        while len(dq) > 0 and nums[dq[-1]] <= val:
            dq.pop()
        dq.append(r)
        if r >= w - 1:
            out.append(nums[dq[0]])
    return out


def largest_rectangle_area(heights):
    stack = []  # ক্রমবর্ধমান উচ্চতার Index ধরে রাখে
    max_area = 0
    n = len(heights)
    for i in range(n + 1):
        if i < n:
            cur_h = heights[i]
        else:
            cur_h = 0  # Sentinel 0: লুপ শেষে বাকি সব Bar পরিষ্কার করে
        while len(stack) > 0 and heights[stack[-1]] > cur_h:
            h = heights[stack.pop()]
            if len(stack) > 0:
                left_bound = stack[-1]
            else:
                left_bound = -1
            width = i - left_bound - 1
            area = h * width
            if area > max_area:
                max_area = area
        stack.append(i)
    return max_area


def shortest_subarray_at_least_k(nums, k):
    # ঋণাত্মক সংখ্যাসহ Subarray যোগফল >= k এর সর্বনিম্ন দৈর্ঘ্য O(n) সময়ে
    prefix = [0]
    for x in nums:
        prefix.append(prefix[-1] + x)
    dq = deque()
    best_len = len(nums) + 1
    for r in range(len(prefix)):
        p_r = prefix[r]
        while len(dq) > 0 and p_r - prefix[dq[0]] >= k:
            cand = r - dq.popleft()
            if cand < best_len:
                best_len = cand
        while len(dq) > 0 and prefix[dq[-1]] >= p_r:
            dq.pop()
        dq.append(r)
    if best_len <= len(nums):
        return best_len
    return -1


