def rank_key(item):
    # আগে বেশি Frequency (-freq), সমান হলে ছোট শব্দ (Lexicographical Order)
    return (-item[0], item[1])


class TrieNode:
    __slots__ = ("children", "freq", "is_end", "top_k")

    def __init__(self):
        self.children = {}
        self.freq = 0
        self.is_end = False
        self.top_k = []  # প্রতিটি উপাদান (freq, word)


class AutocompleteTrie:
    def __init__(self, k=3):
        self.root = TrieNode()
        self.k = k

    def update(self, word, delta=1):
        if len(word) == 0 or delta <= 0:
            return
        node = self.root
        path = [node]
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
            path.append(node)
        node.is_end = True
        node.freq += delta
        total_freq = node.freq

        # দ্বিতীয় পাস: পথের প্রতিটি Ancestor Node-এ Top-K হালনাগাদ
        for anc in path:
            filtered = []
            for entry in anc.top_k:
                if entry[1] != word:
                    filtered.append(entry)
            filtered.append((total_freq, word))
            filtered.sort(key=rank_key)
            anc.top_k = filtered[: self.k]

    def query(self, prefix):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        words = []
        for entry in node.top_k:
            words.append(entry[1])
        return words

    def longest_prefix_tokenize(self, text):
        tokens = []
        i = 0
        n = len(text)
        while i < n:
            node = self.root
            last_end = -1
            for j in range(i, n):
                ch = text[j]
                if ch not in node.children:
                    break
                node = node.children[ch]
                if node.is_end:
                    last_end = j + 1
            if last_end != -1:
                tokens.append(text[i:last_end])
                i = last_end
            else:
                tokens.append(text[i])
                i += 1
        return tokens


trie = AutocompleteTrie(k=2)
seed_queries = [
    ("mlops", 45),
