import math
import random


def stable_softmax_1d(vals):
    m = vals[0]
    for v in vals:
        if v > m:
            m = v
    exps = []
    s = 0.0
    for v in vals:
        if v == -math.inf:
            e = 0.0
        else:
            e = math.exp(v - m)
        exps.append(e)
        s += e
    out = []
    for e in exps:
        out.append(e / s)
    return out


def matmul_2d(A, B):
    # A: (M, K), B: (K, N) -> (M, N)
    m = len(A)
    k = len(A[0])
    n = len(B[0])
    C = []
    for i in range(m):
        row = []
        for j in range(n):
            acc = 0.0
            for p in range(k):
                acc += A[i][p] * B[p][j]
            row.append(acc)
        C.append(row)
    return C


def make_weight(rows, cols, scale, rng):
    mat = []
    for _ in range(rows):
        row = []
        for _ in range(cols):
            row.append(rng.gauss(0.0, scale))
        mat.append(row)
    return mat


class CausalMHAPure:
    def __init__(self, d_model, num_heads, seed=42):
        if d_model % num_heads != 0:
            raise ValueError("d_model must be divisible by num_heads")
        self.d_model = d_model
        self.num_heads = num_heads
        self.d_k = d_model // num_heads
        rng = random.Random(seed)
        scale = 1.0 / math.sqrt(d_model)
        self.W_q = make_weight(d_model, d_model, scale, rng)
        self.W_k = make_weight(d_model, d_model, scale, rng)
        self.W_v = make_weight(d_model, d_model, scale, rng)
        self.W_o = make_weight(d_model, d_model, scale, rng)

    def _split_heads(self, proj):
        # proj: (L, d_model) -> heads: (H, L, d_k)
        heads = []
        for h in range(self.num_heads):
            start = h * self.d_k
            end = start + self.d_k
            h_mat = []
            for t in range(len(proj)):
                h_mat.append(proj[t][start:end])
            heads.append(h_mat)
        return heads

    def forward(self, x, kv_cache=None):
        # x: (L_q, d_model) — একটি Sequence-এর জন্য স্পষ্ট Pure Python ফ্লো
        l_q = len(x)
        q_heads = self._split_heads(matmul_2d(x, self.W_q))
        k_heads = self._split_heads(matmul_2d(x, self.W_k))
        v_heads = self._split_heads(matmul_2d(x, self.W_v))

        t_past = 0
        if kv_cache is not None:
            k_past, v_past = kv_cache
            t_past = len(k_past[0])
            for h in range(self.num_heads):
                k_heads[h] = k_past[h] + k_heads[h]
                v_heads[h] = v_past[h] + v_heads[h]

        l_k = len(k_heads[0])
        inv_sqrt_dk = 1.0 / math.sqrt(self.d_k)

        # প্রতিটি Head-এ Scaled Dot-Product + Generalized Offset Causal Mask
        ctx_heads = []
        for h in range(self.num_heads):
            h_ctx = []
            for i in range(l_q):
                q_pos = t_past + i
                score_row = []
                for j in range(l_k):
                    if j > q_pos:
                        score_row.append(-math.inf)
                    else:
                        dot = 0.0
                        for f in range(self.d_k):
                            dot += q_heads[h][i][f] * k_heads[h][j][f]
                        score_row.append(dot * inv_sqrt_dk)
                weights = stable_softmax_1d(score_row)
                ctx_vec = [0.0] * self.d_k
                for j in range(l_k):
                    w_ij = weights[j]
                    for f in range(self.d_k):
                        ctx_vec[f] += w_ij * v_heads[h][j][f]
                h_ctx.append(ctx_vec)
            ctx_heads.append(h_ctx)

        # Head Merge: (H, L_q, d_k) -> (L_q, d_model), তারপর @ W_o
        merged = []
        for i in range(l_q):
            row = []
            for h in range(self.num_heads):
                for f in range(self.d_k):
                    row.append(ctx_heads[h][i][f])
            merged.append(row)
        out = matmul_2d(merged, self.W_o)
        return out, (k_heads, v_heads)


# ১) Full-Sequence Forward বনাম Prefill (3 Token) + Incremental Decode (3 x 1 Token)
rng_in = random.Random(123)
mha = CausalMHAPure(d_model=8, num_heads=2, seed=42)
X_seq = []
for _ in range(6):
    tok = []
    for _ in range(8):
        tok.append(rng_in.gauss(0.0, 1.0))
    X_seq.append(tok)

out_full, _ = mha.forward(X_seq, kv_cache=None)

out_pre, cache = mha.forward(X_seq[:3], kv_cache=None)
out_inc = list(out_pre)
for step in range(3, 6):
    out_step, cache = mha.forward(X_seq[step : step + 1], kv_cache=cache)
    out_inc.append(out_step[0])

max_diff = 0.0
for i in range(6):
    for j in range(8):
        diff = abs(out_full[i][j] - out_inc[i][j])
        if diff > max_diff:
            max_diff = diff
assert max_diff < 1e-12

# ২) Strict Causality পরীক্ষা: শেষ Token বদলে দিলে আগের ৫টি Token একটুও নড়বে না!
X_pert = []
for row in X_seq:
    X_pert.append(list(row))
for j in range(8):
    X_pert[5][j] += 100.0
out_pert, _ = mha.forward(X_pert, kv_cache=None)
causal_diff = 0.0
for i in range(5):
    for j in range(8):
        diff = abs(out_full[i][j] - out_pert[i][j])
        if diff > causal_diff:
            causal_diff = diff
assert causal_diff < 1e-13
print(f"Pure Python KV Cache max_diff={max_diff:.2e} | strict_causality_diff={causal_diff:.2e} | cache_len={len(cache[0][0])}")

import math
import random


def merge_pair(ids, pair, new_id):
    out = []
    i = 0
    n = len(ids)
    while i < n:
        if i + 1 < n and ids[i] == pair[0] and ids[i + 1] == pair[1]:
            out.append(new_id)
            i += 2
        else:
            out.append(ids[i])
            i += 1
    return out


class DeterministicBPEPure:
    def __init__(self):
        self.merges = []
        self.merge_ranks = {}
        self.vocab = {}
        for b in range(256):
            self.vocab[b] = bytes([b])

    def train(self, text, num_merges):
        ids = list(text.encode("utf-8"))
        for rank in range(num_merges):
            if len(ids) < 2:
                break
            counts = {}
            for i in range(len(ids) - 1):
                pair = (ids[i], ids[i + 1])
                if pair in counts:
                    counts[pair] += 1
                else:
                    counts[pair] = 1
            best_pair = None
            best_cnt = 0
            for pair, cnt in counts.items():
                # সর্বোচ্চ গণনা; সমান হলে ছোট Token জোড়া আগে (Deterministic)
                if cnt > best_cnt or (cnt == best_cnt and (best_pair is None or pair < best_pair)):
                    best_cnt = cnt
                    best_pair = pair
            if best_cnt < 2:
                break
            new_id = 256 + rank
            ids = merge_pair(ids, best_pair, new_id)
            self.merges.append(best_pair)
            self.merge_ranks[best_pair] = rank
            self.vocab[new_id] = self.vocab[best_pair[0]] + self.vocab[best_pair[1]]

    def encode(self, text):
        ids = list(text.encode("utf-8"))
        while len(ids) >= 2:
            best_pair = None
            best_rank = 10**9
            for i in range(len(ids) - 1):
                pair = (ids[i], ids[i + 1])
                if pair in self.merge_ranks:
                    r = self.merge_ranks[pair]
                    if r < best_rank:
                        best_rank = r
                        best_pair = pair
            if best_pair is None:
                break
            ids = merge_pair(ids, best_pair, 256 + best_rank)
        return ids

    def decode(self, ids):
        chunks = []
        for idx in ids:
            chunks.append(self.vocab[idx])
        return b"".join(chunks).decode("utf-8", errors="replace")


def fused_softmax_ce_pure(logits, targets, ignore_index=-100):
    n = len(logits)
    v = len(logits[0])
    grad = []
    for _ in range(n):
        grad.append([0.0] * v)

    n_valid = 0
    for y in targets:
        if y != ignore_index:
            n_valid += 1
    if n_valid == 0:
        return 0.0, grad

    total_loss = 0.0
    for i in range(n):
        y = targets[i]
        if y == ignore_index:
            continue
        row = logits[i]
        m = row[0]
        for z in row:
            if z > m:
                m = z
        exps = []
        sum_exp = 0.0
        for z in row:
            e = math.exp(z - m)
            exps.append(e)
            sum_exp += e
        # Fused Log-Sum-Exp: কখনোই separate log(softmax) নেওয়া হয় না!
        row_loss = -(row[y] - m) + math.log(sum_exp)
        total_loss += row_loss

        for j in range(v):
            prob_j = exps[j] / sum_exp
            if j == y:
                prob_j -= 1.0
            grad[i][j] = prob_j / n_valid

    return total_loss / n_valid, grad


# ১) বাংলা + ইংরেজি UTF-8 টেক্সটে Deterministic BPE যাচাই
bpe = DeterministicBPEPure()
corpus = "ababaa মেশিন লার্নিং মেশিন লার্নিং BPE BPE!"
bpe.train(corpus, num_merges=12)
test_str = "মেশিন লার্নিং ও ababaa BPE!"
encoded = bpe.encode(test_str)
raw_bytes = len(test_str.encode("utf-8"))
assert bpe.decode(encoded) == test_str and len(encoded) < raw_bytes

# ২) Extreme Logits (+/-1000) + ignore_index=-100 সুরক্ষা যাচাই
ext_z = [[1000.0, -1000.0], [-1000.0, 1000.0], [50.0, 90.0]]
ext_y = [1, 1, -100]
l_ext, g_ext = fused_softmax_ce_pure(ext_z, ext_y)
assert math.isfinite(l_ext) and abs(l_ext - 1000.0) < 1e-9
assert g_ext[2][0] == 0.0 and g_ext[2][1] == 0.0

# ৩) Central Finite-Difference Gradient Check
rng = random.Random(2026)
z_std = []
for _ in range(4):
    row = []
    for _ in range(5):
        row.append(rng.gauss(0.0, 2.0))
    z_std.append(row)
y_std = [2, -100, 0, 4]
loss_val, grad_ana = fused_softmax_ce_pure(z_std, y_std)
eps = 1e-6
max_err = 0.0
for i in range(4):
    for j in range(5):
        orig = z_std[i][j]
        z_std[i][j] = orig + eps
        lp, _ = fused_softmax_ce_pure(z_std, y_std)
        z_std[i][j] = orig - eps
        ln, _ = fused_softmax_ce_pure(z_std, y_std)
        z_std[i][j] = orig
        g_num = (lp - ln) / (2.0 * eps)
        err = abs(grad_ana[i][j] - g_num)
        if err > max_err:
            max_err = err
assert max_err < 1e-9
print(f"BPE: UTF-8 bytes={raw_bytes} -> tokens={len(encoded)} (roundtrip OK)")
print(f"Extreme CE loss={l_ext:.1f} | Finite-Diff max_err={max_err:.2e}")
